{
  "category_edits": [
    {
      "category": "sequence_interest",
      "rationale": "Across all four datasets, limit sequences to the most recent 64 positions to reduce distant-context interference. Inference reserves the final position for the appended mask, retaining up to 63 observed items. Preserve chronological nonpadding positions, masked-state readout, positional-table shapes, backbone, scoring, loss and optimizer.",
      "edits": [
        {
          "find": "    # Cloze training: masked targets are not exposed as unmasked shifted inputs.\n    users = [u for u, items in user_train.items() if len(items) >= 2]",
          "replace": "    # Cloze training: masked targets are not exposed as unmasked shifted inputs.\n    maxlen = min(maxlen, 64)\n    users = [u for u, items in user_train.items() if len(items) >= 2]"
        },
        {
          "find": "def _history_to_tensor(history: list[int], maxlen: int, device: torch.device) -> torch.Tensor:\n    seq_arr = np.zeros(maxlen, dtype=np.int64)",
          "replace": "def _history_to_tensor(history: list[int], maxlen: int, device: torch.device) -> torch.Tensor:\n    maxlen = min(maxlen, 64)\n    seq_arr = np.zeros(maxlen, dtype=np.int64)"
        },
        {
          "find": "    maxlen = int(meta.get(\"maxlen\", 128))\n    seq_arr = [0] * maxlen",
          "replace": "    maxlen = min(int(meta.get(\"maxlen\", 128)), 64)\n    seq_arr = [0] * maxlen"
        }
      ]
    }
  ],
  "change_summary": "Cap training, validation and generated-predictor sequences at 64 positions while preserving checkpoint shapes and one BERT4Rec model per dataset."
}
